export function nowIso() { return new Date().toISOString(); }
export function validateVNextDesign(record: unknown): string[] {
  const errors: string[] = [];
  const d = record as Partial<VNextDesign> | null;
  if (!d || typeof d !== "object") return ["record must be an object"];
  if (!d.canonical_id) errors.push("canonical_id is required");
  if (d.schema_version !== VNEXT_SCHEMA_VERSION) errors.push("schema_version is invalid");
  if (!d.created_at) errors.push("created_at is required");
  if (!d.updated_at) errors.push("updated_at is required");
  if (!Number.isInteger(d.revision) || (d.revision || 0) < 1) errors.push("revision must be >= 1");
  if (!d.status || !["DRAFT", "DESIGNED", "RENDER_READY", "RENDERED", "QC_REVIEW", "APPROVED", "COLLECTION_READY", "CAMPAIGN_READY", "PUBLISHED", "ARCHIVED"].includes(d.status)) errors.push("status is invalid");
  if (!d.identity?.name) errors.push("identity.name is required");
  if (!d.origin?.type) errors.push("origin.type is required");
  if (!Array.isArray(d.legacy_aliases)) errors.push("legacy_aliases must be an array");
  for (const vector of [d.predicted_evs, d.observed_evs]) if (vector) for (const axis of EVS_AXES) if (typeof vector[axis] !== "number" || vector[axis] < 0 || vector[axis] > 1) errors.push(`${axis} must be between 0 and 1`);
  return errors;
}

export const MoodoorIdService = {
  next(existing: VNextDesign[]) {
    const max = existing.reduce((value, d) => Math.max(value, Number(d.canonical_id.match(/^MD-(\d+)$/)?.[1] || 0)), 0);
    return `MD-${String(max + 1).padStart(6, "0")}`;
  },
};

const allowed: Record<VNextStatus, VNextStatus[]> = { DRAFT: ["DESIGNED", "ARCHIVED"], DESIGNED: ["DRAFT", "ARCHIVED"], ARCHIVED: ["DRAFT"], RENDER_READY: [], RENDERED: [], QC_REVIEW: [], APPROVED: [], COLLECTION_READY: [], CAMPAIGN_READY: [], PUBLISHED: [] };
export const MoodoorStatusService = { transition(current: VNextStatus, next: VNextStatus) { if (next === current) return true; if (!allowed[current]?.includes(next)) throw new Error(`Invalid Sprint 2 transition: ${current} → ${next}`); return true; } };

export const MoodoorDesignRepository = {
  list(): VNextDesign[] { try { return JSON.parse(localStorage.getItem(VNEXT_KEYS.designs) || "[]"); } catch { return []; } },
  get(id: string) { return MoodoorDesignRepository.list().find((d) => d.canonical_id === id); },
  saveAll(designs: VNextDesign[]) { localStorage.setItem(VNEXT_KEYS.designs, JSON.stringify(designs)); localStorage.setItem(VNEXT_KEYS.schemaVersion, VNEXT_SCHEMA_VERSION); },
  create(input: Omit<VNextDesign, "canonical_id" | "created_at" | "updated_at" | "revision" | "status" | "schema_version">) {
    const existing = MoodoorDesignRepository.list(); const at = nowIso(); const record: VNextDesign = { ...input, interpretation: input.interpretation ?? null, interpretation_candidates: input.interpretation_candidates ?? [], downstream_stale: input.downstream_stale ?? false, composition: input.composition ?? null, composition_candidates: input.composition_candidates ?? [], greenery_architecture: input.greenery_architecture ?? null, greenery_architecture_candidates: input.greenery_architecture_candidates ?? [], floral_orchestration: input.floral_orchestration ?? null, floral_orchestration_candidates: input.floral_orchestration_candidates ?? [], botanical_qualification: input.botanical_qualification ?? null, botanical_qualification_candidates: input.botanical_qualification_candidates ?? [], botanical_selection: input.botanical_selection ?? null, botanical_selection_candidates: input.botanical_selection_candidates ?? [], inventory_resolution: input.inventory_resolution ?? null, inventory_resolution_candidates: input.inventory_resolution_candidates ?? [], blueprint: input.blueprint ?? null, blueprint_candidates: input.blueprint_candidates ?? [], ecr: input.ecr ?? null, ecr_candidates: input.ecr_candidates ?? [], render_package: input.render_package ?? null, render_package_candidates: input.render_package_candidates ?? [], render_result: input.render_result ?? null, qc_result: input.qc_result ?? null, qc_result_candidates: input.qc_result_candidates ?? [], collection_ids: input.collection_ids ?? [], canonical_id: MoodoorIdService.next(existing), schema_version: VNEXT_SCHEMA_VERSION, created_at: at, updated_at: at, revision: 1, status: "DRAFT" };
    const errors = validateVNextDesign(record); if (errors.length) throw new Error(errors.join("; ")); MoodoorDesignRepository.saveAll([...existing, record]); MoodoorActivityRepository.append({ design_id: record.canonical_id, action: "created", label: "Design created", at, revision: 1 }); return record;
  },
  update(id: string, patch: Partial<Pick<VNextDesign, "identity" | "design" | "essence" | "territory" | "predicted_evs" | "observed_evs" | "effective_evs" | "interpretation" | "interpretation_candidates" | "downstream_stale" | "composition" | "composition_candidates" | "greenery_architecture" | "greenery_architecture_candidates" | "floral_orchestration" | "floral_orchestration_candidates" | "botanical_qualification" | "botanical_qualification_candidates" | "botanical_selection" | "botanical_selection_candidates" | "inventory_resolution" | "inventory_resolution_candidates" | "blueprint" | "blueprint_candidates" | "ecr" | "ecr_candidates" | "render_package" | "render_package_candidates" | "render_result" | "qc_result" | "qc_result_candidates" | "collection_ids">>) {
    const existing = MoodoorDesignRepository.list(); const index = existing.findIndex((d) => d.canonical_id === id); if (index < 0) throw new Error("vNext design not found"); const current = existing[index]; const next = { ...current, ...patch, updated_at: nowIso(), revision: current.revision + 1 }; const errors = validateVNextDesign(next); if (errors.length) throw new Error(errors.join("; ")); existing[index] = next; MoodoorDesignRepository.saveAll(existing); MoodoorActivityRepository.append({ design_id: id, action: "edited", label: "Design edited", detail: Object.keys(patch).join(", "), at: next.updated_at, revision: next.revision }); return next;
  },
    transition(id: string, status: VNextStatus) { const current = MoodoorDesignRepository.get(id); if (!current) throw new Error("vNext design not found"); MoodoorStatusService.transition(current.status, status); const all = MoodoorDesignRepository.list(); const index = all.findIndex((d) => d.canonical_id === id); const at = nowIso(); all[index] = { ...all[index], status, updated_at: at, revision: all[index].revision + 1 }; MoodoorDesignRepository.saveAll(all); MoodoorActivityRepository.append({ design_id: id, action: status === "ARCHIVED" ? "archived" : "restored", label: status === "ARCHIVED" ? "Design archived" : "Design restored", at, revision: all[index].revision }); return all[index]; },
};
export const MoodoorActivityRepository = { list(designId?: string): ActivityEntry[] { try { const all = JSON.parse(localStorage.getItem(VNEXT_KEYS.activity) || "[]"); return designId ? all.filter((e: ActivityEntry) => e.design_id === designId) : all; } catch { return []; } }, append(entry: Omit<ActivityEntry, "id">) { const all = MoodoorActivityRepository.list(); const next = { ...entry, id: `ACT-${String(all.length + 1).padStart(6, "0")}` }; localStorage.setItem(VNEXT_KEYS.activity, JSON.stringify([...all, next])); return next; } };
